def enclosed(n, marks):
    blocked=set(marks); reach=set(); q=deque()
    for r in range(n):
      for c in [0,n-1]:
       if (r,c) not in blocked: reach.add((r,c)); q.append((r,c))
    for c in range(n):
      for r in [0,n-1]:
       if (r,c) not in blocked and (r,c) not in reach: reach.add((r,c)); q.append((r,c))
    while q:
      r,c=q.popleft()
      for rr,cc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
       if 0<=rr<n and 0<=cc<n and (rr,cc) not in blocked and (rr,cc) not in reach:
        reach.add((rr,cc));q.append((rr,cc))
    return {(r,c) for r in range(n) for c in range(n) if (r,c) not in blocked and (r,c) not in reach}
